\set ON_ERROR_STOP on
begin;
create temporary table context_assertions(n int);insert into context_assertions values(0);grant all on context_assertions to service_role;
create function pg_temp.ok(v boolean,label text)returns void language plpgsql as $$begin if v is distinct from true then raise exception'CONTEXT FAIL: %',label;end if;update context_assertions set n=n+1;end$$;
create function pg_temp.no(command text,needle text,label text)returns void language plpgsql as $$begin begin execute command;exception when others then if position(needle in sqlerrm)>0 then perform pg_temp.ok(true,label);return;end if;raise;end;raise exception'CONTEXT FAIL allowed: %',label;end$$;
insert into auth.users(id,email,is_anonymous)values('f8300000-0000-4000-8000-000000000001','photo-context-owner@fixture.invalid',false),('f8300000-0000-4000-8000-000000000002','photo-context-other@fixture.invalid',false);
create temporary table f as select 'f8300000-0000-4000-8000-000000000001'::uuid actor,'f8300000-0000-4000-8000-000000000002'::uuid other,(select org_id from memberships where user_id='f8300000-0000-4000-8000-000000000001'and role='owner'limit 1)org,'f8300000-0000-4000-8000-000000000011'::uuid listing;
grant select on f to service_role;
-- Context authority is tested on a synthetic paid workspace.
update orgs set plan='starter',plan_source='manual' where id=(select org from f);
insert into listings(id,org_id,agent_id,address)select listing,org,actor,'Synthetic context property'from f;
update app_config set value=jsonb_set(value,'{enabled}','true')where key='photo_quality';
create function pg_temp.seed(label text)returns jsonb language plpgsql as $$begin
 perform serving_operation_begin((select actor from f),(select org from f),'photo-context:'||label,'/ai-photo',repeat('d',64));
 return photo_quality_begin((select actor from f),(select org from f),'photo-context:'||label,(select listing from f),'declutter',null,null,jsonb_build_object('sha256',repeat('a',64),'bytes',60000,'mime','image/jpeg','width',1024,'height',768));end$$;
select pg_temp.ok(not has_function_privilege('anon','public.photo_quality_set_context(uuid,uuid,text,jsonb)','execute')and not has_function_privilege('authenticated','public.photo_quality_set_context(uuid,uuid,text,jsonb)','execute'),'public callers cannot supply private judge context');
select pg_temp.ok(not has_function_privilege('service_role','public.photo_quality_bind_before_context(uuid,uuid,uuid,uuid)','execute'),'service cannot bypass context wrapper through previous bind');
set local role service_role;
create temporary table b as select pg_temp.seed('happy')x;grant select,update on b to service_role;
select pg_temp.no($q$select photo_quality_check_bind((select actor from f),(select(x#>>'{check,id}')::uuid from b),gen_random_uuid(),gen_random_uuid())$q$,'context is missing','missing context refuses binding before provider funding can be used');
select pg_temp.no($q$select photo_quality_set_context((select other from f),(select(x#>>'{evidence,id}')::uuid from b),repeat('d',64),'{}')$q$,'RP404','other actor cannot set context');
select pg_temp.no($q$select photo_quality_set_context((select actor from f),(select(x#>>'{evidence,id}')::uuid from b),repeat('e',64),'{"edit":"declutter","style":null,"instruction":""}')$q$,'RP409','context requires admitted complete body hash');
select pg_temp.no($q$select photo_quality_set_context((select actor from f),(select(x#>>'{evidence,id}')::uuid from b),repeat('d',64),'[]')$q$,'RP400','array is not judge context');
select pg_temp.no($q$select photo_quality_set_context((select actor from f),(select(x#>>'{evidence,id}')::uuid from b),repeat('d',64),'{"edit":"stage","style":null,"instruction":""}')$q$,'RP400','edit cannot drift from retained evidence');
select pg_temp.no($q$select photo_quality_set_context((select actor from f),(select(x#>>'{evidence,id}')::uuid from b),repeat('d',64),'{"edit":"declutter","style":"modern","instruction":""}')$q$,'RP400','style cannot drift from retained evidence');
select pg_temp.no($q$select photo_quality_set_context((select actor from f),(select(x#>>'{evidence,id}')::uuid from b),repeat('d',64),'{"edit":"declutter","style":null,"instruction":"","model":"override"}')$q$,'RP400','no model or extra fields in context');
select pg_temp.no($q$select photo_quality_set_context((select actor from f),(select(x#>>'{evidence,id}')::uuid from b),repeat('d',64),'{"edit":"declutter","style":null,"instruction":10}')$q$,'RP400','instruction must be text');
select pg_temp.no($q$select photo_quality_set_context((select actor from f),(select(x#>>'{evidence,id}')::uuid from b),repeat('d',64),jsonb_build_object('edit','declutter','style',null,'instruction',repeat('x',601)))$q$,'RP400','601-character instruction refused');
update b set x=photo_quality_set_context((select actor from f),(x#>>'{evidence,id}')::uuid,repeat('d',64),'{"edit":"declutter","style":null,"instruction":"Remove loose clutter only."}');
select pg_temp.ok((select x#>>'{evidence,judge_context,instruction}'='Remove loose clutter only.'from b),'exact instructions retained');
select pg_temp.ok(photo_quality_set_context((select actor from f),(select(x#>>'{evidence,id}')::uuid from b),repeat('d',64),'{"instruction":"Remove loose clutter only.","style":null,"edit":"declutter"}')#>>'{evidence,judge_context,instruction}'='Remove loose clutter only.','identical JSON context idempotent');
select pg_temp.no($q$select photo_quality_set_context((select actor from f),(select(x#>>'{evidence,id}')::uuid from b),repeat('d',64),'{"edit":"declutter","style":null,"instruction":"Change the scope."}')$q$,'immutable','changed context refused');
select pg_temp.no($q$select photo_quality_check_bind((select actor from f),(select(x#>>'{check,id}')::uuid from b),gen_random_uuid(),gen_random_uuid())$q$,'lease expired','saved context reaches original current lease guard');
create temporary table unicode as select pg_temp.seed('unicode')x;grant select,update on unicode to service_role;
update unicode set x=photo_quality_set_context((select actor from f),(x#>>'{evidence,id}')::uuid,repeat('d',64),jsonb_build_object('edit','declutter','style',null,'instruction',repeat(chr(128512),600)));
select pg_temp.ok((select octet_length(x#>>'{evidence,judge_context,instruction}')=2400 from unicode),'600 Unicode scalar characters at2400UTF8bytes accepted');
create temporary table late as select pg_temp.seed('late')x;grant select on late to service_role;
reset role;update photo_quality_checks set judge_started_at=now(),state='checking'where id=(select(x#>>'{check,id}')::uuid from late);set local role service_role;
select pg_temp.no($q$select photo_quality_set_context((select actor from f),(select(x#>>'{evidence,id}')::uuid from late),repeat('d',64),'{"edit":"declutter","style":null,"instruction":""}')$q$,'after dispatch','new context cannot be added after judge fence');
select pg_temp.ok((select count(*)=0 from serving_cost_reservations where actor_id=(select actor from f)),'context tests never fabricate a paid provider attempt');
reset role;select'Photo context assertions: '||n from context_assertions;
rollback;
